/* ============ API LAYER ============
   Talks to the ASP.NET Core backend over HTTP.
   The site is served by that same backend, so "/api/..." resolves
   to http://localhost:5000/api/... with no CORS involved.      */

const store = {
  get: (k, f) => { try { const v = JSON.parse(localStorage.getItem(k)); return v === null ? f : v; } catch { return f; } },
  set: (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch {} },
};

const API_BASE = "/api";

/** Every request goes through here: attaches the JWT, unwraps the error message. */
async function http(path, options) {
  options = options || {};
  const headers = { "Content-Type": "application/json" };
  const token = localStorage.getItem("dw_token");
  if (token) headers["Authorization"] = "Bearer " + token;

  let res;
  try {
    res = await fetch(API_BASE + path, {
      method: options.method || "GET",
      headers: headers,
      body: options.body ? JSON.stringify(options.body) : undefined,
    });
  } catch (networkError) {
    throw new Error("Cannot reach the server. Make sure the backend is running.");
  }

  if (res.status === 204) return null;

  const text = await res.text();
  let data = null;
  if (text) { try { data = JSON.parse(text); } catch { data = null; } }

  if (!res.ok) {
    const msg = (data && (data.message || data.title)) || "Request failed (" + res.status + ")";
    throw new Error(msg);
  }
  return data;
}

/** Sends one file as multipart/form-data. No Content-Type header is set here:
    the browser has to add its own, because it carries the multipart boundary. */
async function upload(path, file) {
  const form = new FormData();
  form.append("file", file);

  const headers = {};
  const token = localStorage.getItem("dw_token");
  if (token) headers["Authorization"] = "Bearer " + token;

  let res;
  try {
    res = await fetch(API_BASE + path, { method: "POST", headers: headers, body: form });
  } catch (networkError) {
    throw new Error("Cannot reach the server. Make sure the backend is running.");
  }

  const text = await res.text();
  let data = null;
  if (text) { try { data = JSON.parse(text); } catch { data = null; } }

  if (!res.ok) {
    // 413 is the server refusing the request for its size before reading it.
    if (res.status === 413) throw new Error("That file is too large. A CV can be up to 2 MB.");
    const msg = (data && (data.message || data.title)) || "Upload failed (" + res.status + ")";
    throw new Error(msg);
  }
  return data;
}

const qs = (obj) => {
  const parts = [];
  Object.keys(obj).forEach(k => {
    if (obj[k] !== "" && obj[k] !== null && obj[k] !== undefined)
      parts.push(encodeURIComponent(k) + "=" + encodeURIComponent(obj[k]));
  });
  return parts.length ? "?" + parts.join("&") : "";
};

