/** Downloads a CSV report, carrying the bearer token with the request. */
function downloadCsv(path, filename) {
  return downloadFile(path, filename, "Could not generate the report.");
}

/** Downloads any file from the API (a report or a CV) and saves it under the
    given name. A plain link cannot be used, because it would not carry the
    sign-in token and the server would refuse it. */
async function downloadFile(path, filename, failText) {
  const token = localStorage.getItem("dw_token");
  try {
    const res = await fetch(API_BASE + path, {
      headers: token ? { Authorization: "Bearer " + token } : {},
    });
    if (!res.ok) throw new Error(failText || "Could not download the file.");
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  } catch (e) {
    alert(e.message || failText || "Could not download the file.");
  }
}

