/** Star display used by ratings and profiles. */
function Stars({ value, size }) {
  const v = Math.round(Number(value) || 0);
  return (
    <span style={{ color: "#f59e0b", letterSpacing: 1, fontSize: size || 14 }}>
      {"\u2605".repeat(v)}<span style={{ color: "#d9dee8" }}>{"\u2605".repeat(5 - v)}</span>
    </span>
  );
}

/** Coloured status pill, built from the existing jc-badge class. */
function StatusBadge({ status }) {
  const map = {
    pending:   ["#fef3e2", "#b45309"],
    accepted:  ["#e8f1fd", "#1565d8"],
    completed: ["#e6f6ec", "#16a34a"],
    rejected:  ["#fdecec", "#dc2626"],
    paid:      ["#e6f6ec", "#16a34a"],
    open:      ["#e6f6ec", "#16a34a"],
    closed:    ["#f1f5f9", "#64748b"],
  };
  const c = map[status] || ["#f1f5f9", "#64748b"];
  return <span className="jc-badge" style={{ background: c[0], color: c[1] }}>{status}</span>;
}

