/* ============ JOBS ============ */
const JOB_ICONS = {
  Construction:["fa-helmet-safety","ic-blue"], Agriculture:["fa-seedling","ic-green"],
  Manufacturing:["fa-industry","ic-orange"], Transportation:["fa-truck","ic-blue"],
  "Domestic Services":["fa-house","ic-pink"], Cleaning:["fa-broom","ic-green"], Security:["fa-shield-halved","ic-purple"] };

function Jobs({ user, query }) {
  const blank = {
    search: query.search || "", category: query.category || "", location: "",
    district: "", minPay: "", maxPay: "", skills: "",
    urgentOnly: false, availableOnly: true, verifiedOnly: false, sort: "relevance"
  };

  const [f, setF] = useState(blank);
  const [jobs, setJobs] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [showMore, setShowMore] = useState(false);
  const [categories, setCategories] = useState([]);

  const set = (k) => (e) =>
    setF(Object.assign({}, f, { [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value }));

  // Categories come from the database so the admin can change the list.
  useEffect(() => {
    API.categories()
      .then(list => setCategories((list || []).map(c => c.name)))
      .catch(() => setCategories(Object.keys(JOB_ICONS)));
  }, []);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    const t = setTimeout(() => {
      API.jobs(f)
         .then(res => {
           if (cancelled) return;
           // The API now returns a paged envelope.
           const list = Array.isArray(res) ? res : (res.jobs || []);
           setJobs(list);
           setTotal(Array.isArray(res) ? list.length : (res.total || 0));
         })
         .catch(() => { if (!cancelled) { setJobs([]); setTotal(0); } })
         .finally(() => { if (!cancelled) setLoading(false); });
    }, 250);
    return () => { cancelled = true; clearTimeout(t); };
  }, [f.search, f.category, f.location, f.district, f.minPay, f.maxPay,
      f.skills, f.urgentOnly, f.availableOnly, f.verifiedOnly, f.sort]);

  const apply = async (job) => {
    if (!user) { alert("Please login or register as a Worker to apply for jobs."); go("/login"); return; }
    try {
      await API.apply(job.id);
      alert('Application sent for "' + job.title + '". The employer will be notified.');
    }
    catch (e) { alert(e.message); }
  };

  return (
    <React.Fragment>
      <section className="page-hero"><div className="container">
        <span className="eyebrow">Find Jobs</span>
        <h1>Find Your Next <span className="accent">Daily Job</span> Today</h1>
        <p>Browse verified job openings across Sri Lanka. Filter by category, location and pay to find the right work for you.</p>
      </div></section>

      <section className="section" style={{paddingTop:0}}><div className="container">
        <div className="job-filters">
          <input placeholder="Search job title or keyword…" value={f.search} onChange={set("search")}
                 aria-label="Search jobs" />
          <select value={f.category} onChange={set("category")} aria-label="Category">
            <option value="">All Categories</option>
            {categories.map(c => <option key={c}>{c}</option>)}
          </select>
          <input placeholder="Location (e.g. Colombo)" value={f.location} onChange={set("location")}
                 aria-label="Location" />
          <button className="btn btn-primary" onClick={() => setShowMore(!showMore)}>
            <i className="fa-solid fa-sliders"></i> {showMore ? "Fewer Filters" : "More Filters"}
          </button>
        </div>

        {showMore && (
          <div className="dash-panel" style={{marginTop:14}}>
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="fl-min">Minimum wage (Rs.)</label>
                <input id="fl-min" type="number" min="0" placeholder="e.g. 1500"
                       value={f.minPay} onChange={set("minPay")} />
              </div>
              <div className="form-group">
                <label htmlFor="fl-max">Maximum wage (Rs.)</label>
                <input id="fl-max" type="number" min="0" placeholder="e.g. 3000"
                       value={f.maxPay} onChange={set("maxPay")} />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="fl-skills">Skills</label>
                <input id="fl-skills" placeholder="e.g. masonry, painting"
                       value={f.skills} onChange={set("skills")} />
              </div>
              <div className="form-group">
                <label htmlFor="fl-sort">Sort by</label>
                <select id="fl-sort" value={f.sort} onChange={set("sort")}>
                  <option value="relevance">Most relevant</option>
                  <option value="newest">Newest first</option>
                  <option value="wage_high">Highest wage</option>
                  <option value="wage_low">Lowest wage</option>
                </select>
              </div>
            </div>

            <div style={{display:"flex",gap:20,flexWrap:"wrap",marginTop:4}}>
              <label style={{display:"flex",alignItems:"center",gap:8,fontSize:14,cursor:"pointer"}}>
                <input type="checkbox" checked={f.availableOnly} onChange={set("availableOnly")}
                       style={{width:"auto",margin:0}} />
                Still hiring
              </label>
              <label style={{display:"flex",alignItems:"center",gap:8,fontSize:14,cursor:"pointer"}}>
                <input type="checkbox" checked={f.urgentOnly} onChange={set("urgentOnly")}
                       style={{width:"auto",margin:0}} />
                Urgent jobs only
              </label>
              <label style={{display:"flex",alignItems:"center",gap:8,fontSize:14,cursor:"pointer"}}>
                <input type="checkbox" checked={f.verifiedOnly} onChange={set("verifiedOnly")}
                       style={{width:"auto",margin:0}} />
                Verified employers only
              </label>
              <button className="btn btn-outline btn-sm" style={{marginLeft:"auto"}}
                      onClick={() => setF(blank)}>
                <i className="fa-solid fa-rotate-left"></i> Reset
              </button>
            </div>
          </div>
        )}

        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",
                     margin:"18px 0 4px",flexWrap:"wrap",gap:10}}>
          <b style={{color:"var(--text)",fontSize:15}}>
            {loading ? "Searching…" : total + (total === 1 ? " job found" : " jobs found")}
          </b>
          {!loading && jobs.length > 0 && (
            <span style={{color:"var(--muted)",fontSize:13}}>
              Showing {jobs.length} of {total}
            </span>
          )}
        </div>

        <div className="jobs-grid">
          {loading && (
            <div className="no-results">
              <i className="fa-solid fa-spinner fa-spin" style={{fontSize:30,display:"block",marginBottom:12}}></i>
              Searching jobs…
            </div>)}
          {!loading && jobs.length === 0 && (
            <div className="no-results">
              <i className="fa-regular fa-face-frown" style={{fontSize:34,display:"block",marginBottom:12}}></i>
              No jobs match your search. Try widening your filters.
            </div>)}
          {!loading && jobs.map(j => {
            const [icon, cls] = JOB_ICONS[j.category] || ["fa-briefcase","ic-navy"];
            return (
              <article className="job-card" key={j.id}>
                <div className="jc-top">
                  <div className={"jc-ic " + cls}><i className={"fa-solid " + icon}></i></div>
                  <div>
                    <h4><a href={"#/job?id=" + j.id} style={{color:"inherit"}}>{j.title}</a></h4>
                    <span className="jc-cat">{j.category} · by {j.employerName}</span>
                  </div>
                </div>
                <div className="jc-meta">
                  <span><i className="fa-solid fa-location-dot"></i>{j.location}</span>
                  {j.urgent && <span className="jc-badge urgent">Urgent</span>}
                  {j.employerVerified && <span className="jc-badge verified">
                    <i className="fa-solid fa-circle-check"></i> Verified Employer
                  </span>}
                </div>
                <div className="jc-pay">Rs. {Number(j.pay).toLocaleString()} <small style={{color:"var(--muted)",fontWeight:500}}>/ {j.per}</small></div>
                <div className="jc-foot">
                  <button className="btn btn-primary btn-sm" onClick={() => apply(j)}><i className="fa-solid fa-paper-plane"></i> Apply Now</button>
                  <a className="btn btn-outline btn-sm" href={"#/job?id=" + j.id}>Details</a>
                </div>
              </article>);
          })}
        </div>
      </div></section>
    </React.Fragment>
  );
}

