/**
 * Project management and recruitment tracking, for organizations only.
 *
 * An individual employer posts a job at a time; an organization runs projects
 * that need a number of people across several postings. This shows each
 * project's recruitment position and cost, worked out from the real jobs,
 * applications and payments behind it rather than from anything typed in here.
 */
function ProjectsPanel({ onChanged }) {
  const [data, setData] = useState(null);
  const [msg, setMsg] = useState(null);
  const [busy, setBusy] = useState(false);
  const [open, setOpen] = useState(null);      // project id whose postings are expanded
  const [editing, setEditing] = useState(null); // project being edited, or "new"

  const blank = { name:"", description:"", location:"", district:"",
                  workersRequired:"", budget:"", startDate:"", endDate:"", status:"planning" };
  const [f, setF] = useState(blank);
  const set = (k) => (e) => setF(Object.assign({}, f, { [k]: e.target.value }));

  const load = () => API.projects().then(setData).catch(() => setData({ projects: [] }));
  useEffect(() => { load(); }, []);

  const startNew = () => { setF(blank); setEditing("new"); setMsg(null); };

  const startEdit = (p) => {
    setF({
      name: p.name || "", description: p.description || "",
      location: p.location || "", district: p.district || "",
      workersRequired: p.workersRequired ? String(p.workersRequired) : "",
      budget: p.budget ? String(p.budget) : "",
      startDate: p.startDate ? String(p.startDate).slice(0,10) : "",
      endDate: p.endDate ? String(p.endDate).slice(0,10) : "",
      status: p.status || "planning"
    });
    setEditing(p.id);
    setMsg(null);
  };

  const submit = async (e) => {
    e.preventDefault();
    setMsg(null);
    if (f.name.trim().length < 3)
      return setMsg({ type:"error", text:"Give the project a name of at least 3 characters." });

    setBusy(true);
    const payload = {
      name: f.name.trim(), description: f.description.trim(),
      location: f.location.trim(), district: (f.district || f.location).trim(),
      workersRequired: Number(f.workersRequired) || 0,
      budget: Number(f.budget) || 0,
      startDate: f.startDate || null, endDate: f.endDate || null,
      status: f.status
    };
    try {
      if (editing === "new") await API.createProject(payload);
      else await API.updateProject(editing, payload);
      setMsg({ type:"success", text: editing === "new" ? "Project created." : "Project updated." });
      setEditing(null);
      load();
      if (onChanged) onChanged();
    } catch (err) {
      setMsg({ type:"error", text: err.message });
    }
    setBusy(false);
  };

  const remove = async (p) => {
    if (!confirm('Remove the project "' + p.name + '"?\n\n' +
                 'Any job postings under it are kept — they simply stop belonging to a project.')) return;
    try {
      const r = await API.deleteProject(p.id);
      setMsg({ type:"success", text: r.message });
      load();
      if (onChanged) onChanged();
    } catch (err) {
      setMsg({ type:"error", text: err.message });
    }
  };

  if (!data) return <div className="dash-panel"><h4>Projects</h4><p style={{color:"var(--muted)"}}>Loading…</p></div>;

  const s = data.summary || {};
  const list = data.projects || [];

  return (
    <React.Fragment>
      <div className="dash-stats">
        <div className="dash-stat"><small>Projects</small><b>{s.total || 0}</b></div>
        <div className="dash-stat"><small>Workers Needed</small><b>{s.workersRequired || 0}</b></div>
        <div className="dash-stat"><small>Hired</small><b>{s.hired || 0}</b></div>
        <div className="dash-stat"><small>Still to Hire</small><b>{s.stillNeeded || 0}</b></div>
      </div>

      <div className="dash-panel">
        <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
          <h4 style={{margin:0}}>Projects ({list.length})</h4>
          <button className="btn btn-primary btn-sm" style={{marginLeft:"auto"}} onClick={startNew}>
            <i className="fa-solid fa-plus"></i> New Project
          </button>
        </div>
        <p style={{color:"var(--muted)",fontSize:13,marginTop:6}}>
          Group your job postings by site, contract or season, and track hiring and cost across each one.
        </p>

        {msg && <div className={"form-msg " + msg.type}>{msg.text}</div>}

        {editing && (
          <form onSubmit={submit} style={{borderTop:"1px solid var(--border,#e2e8f0)",paddingTop:16,marginTop:4}}>
            <h5 style={{marginTop:0}}>{editing === "new" ? "New Project" : "Edit Project"}</h5>
            <div className="form-group">
              <label htmlFor="pr-name">Project Name</label>
              <input id="pr-name" value={f.name} onChange={set("name")}
                     placeholder="e.g. Kandy Road Housing Site" required />
            </div>
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="pr-loc">Location</label>
                <input id="pr-loc" value={f.location} onChange={set("location")} placeholder="e.g. Kandy" />
              </div>
              <div className="form-group">
                <label htmlFor="pr-dist">District</label>
                <input id="pr-dist" value={f.district} onChange={set("district")} placeholder="e.g. Kandy" />
              </div>
            </div>
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="pr-workers">Workers Required</label>
                <input id="pr-workers" type="number" min="0" max="10000"
                       value={f.workersRequired} onChange={set("workersRequired")} placeholder="25" />
              </div>
              <div className="form-group">
                <label htmlFor="pr-budget">Budget (Rs.)</label>
                <input id="pr-budget" type="number" min="0" value={f.budget}
                       onChange={set("budget")} placeholder="500000" />
              </div>
            </div>
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="pr-start">Start Date</label>
                <input id="pr-start" type="date" value={f.startDate} onChange={set("startDate")} />
              </div>
              <div className="form-group">
                <label htmlFor="pr-end">End Date</label>
                <input id="pr-end" type="date" value={f.endDate} onChange={set("endDate")} />
              </div>
            </div>
            <div className="form-group">
              <label htmlFor="pr-status">Status</label>
              <select id="pr-status" value={f.status} onChange={set("status")}>
                <option value="planning">Planning</option>
                <option value="active">Active</option>
                <option value="completed">Completed</option>
                <option value="cancelled">Cancelled</option>
              </select>
            </div>
            <div className="form-group">
              <label htmlFor="pr-desc">Description</label>
              <textarea id="pr-desc" rows="2" value={f.description} onChange={set("description")}
                        placeholder="What this project involves…"></textarea>
            </div>
            <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
              <button className="btn btn-primary" type="submit" disabled={busy}>
                {busy ? "Saving…" : (editing === "new" ? "Create Project" : "Save Changes")}
              </button>
              <button className="btn btn-outline" type="button" onClick={() => setEditing(null)}>Cancel</button>
            </div>
          </form>
        )}

        {list.length === 0 && !editing
          ? <Empty icon="fa-diagram-project"
                   text="No projects yet. Create one to group your postings and track recruitment across them." />
          : <ul className="activity">{list.map(p => (
              <li key={p.id} style={{alignItems:"flex-start",flexWrap:"wrap",gap:12}}>
                <div className={"a-ic " + (p.status === "completed" ? "ic-green" : "ic-blue")}>
                  <i className="fa-solid fa-diagram-project"></i>
                </div>
                <div style={{flex:"1 1 320px"}}>
                  <b>{p.name} <StatusBadge status={p.status} /></b>
                  <small>
                    {p.location && <React.Fragment>{p.location} · </React.Fragment>}
                    {p.jobsPosted} posting(s) · {p.applicants} applicant(s)
                    {p.description && <React.Fragment><br />{p.description}</React.Fragment>}
                  </small>

                  {/* Recruitment progress, measured against what the project needs */}
                  <div style={{marginTop:10}}>
                    <div style={{display:"flex",justifyContent:"space-between",fontSize:12.5,
                                 color:"var(--muted)",marginBottom:4}}>
                      <span>Hired {p.hired} of {p.workersRequired}</span>
                      <span>{p.stillNeeded > 0 ? p.stillNeeded + " still needed" : "Fully staffed"}</span>
                    </div>
                    <div style={{height:8,borderRadius:99,background:"var(--bg-soft,#eef3f9)",overflow:"hidden"}}>
                      <div style={{height:"100%",width:Math.min(100, p.fillRate) + "%",borderRadius:99,
                                   background: p.stillNeeded > 0 ? "var(--blue,#1565d8)" : "var(--green,#16a34a)"}}></div>
                    </div>
                  </div>

                  <div style={{display:"flex",gap:18,flexWrap:"wrap",marginTop:10,fontSize:13}}>
                    <span><b style={{color:"var(--navy,#0b2447)"}}>{money(p.committed)}</b>
                          <small style={{color:"var(--muted)",display:"block"}}>Committed</small></span>
                    <span><b style={{color:"var(--green,#16a34a)"}}>{money(p.paid)}</b>
                          <small style={{color:"var(--muted)",display:"block"}}>Paid</small></span>
                    <span><b style={{color: p.outstanding > 0 ? "var(--orange,#f59e0b)" : "var(--muted)"}}>{money(p.outstanding)}</b>
                          <small style={{color:"var(--muted)",display:"block"}}>Outstanding</small></span>
                    {p.budget > 0 && (
                      <span><b style={{color: p.overBudget ? "#b91c1c" : "var(--navy,#0b2447)"}}>
                              {p.budgetUsed}%</b>
                            <small style={{color:"var(--muted)",display:"block"}}>
                              of {money(p.budget)}{p.overBudget ? " — over budget" : ""}
                            </small></span>
                    )}
                  </div>

                  {open === p.id && p.jobs && p.jobs.length > 0 && (
                    <div style={{marginTop:12,borderTop:"1px solid var(--border,#e2e8f0)",paddingTop:10}}>
                      {p.jobs.map(j => (
                        <div key={j.id} style={{display:"flex",gap:10,alignItems:"center",
                                                flexWrap:"wrap",padding:"6px 0",fontSize:13.5}}>
                          <a href={"#/job?id=" + j.id} style={{fontWeight:600}}>{j.title}</a>
                          <StatusBadge status={j.status} />
                          <span style={{color:"var(--muted)"}}>
                            {money(j.pay)} / {j.per} · hired {j.hired} of {j.workersNeeded} · {j.applicants} applicant(s)
                          </span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
                <span className="when" style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
                  {p.jobs && p.jobs.length > 0 && (
                    <button className="btn btn-sm btn-outline"
                            onClick={() => setOpen(open === p.id ? null : p.id)}>
                      {open === p.id ? "Hide postings" : "View postings (" + p.jobs.length + ")"}
                    </button>
                  )}
                  <button className="btn btn-sm btn-outline" onClick={() => startEdit(p)}>
                    <i className="fa-solid fa-pen"></i> Edit
                  </button>
                  <button className="btn btn-sm btn-outline" onClick={() => remove(p)}>Remove</button>
                </span>
              </li>))}
            </ul>}
      </div>
    </React.Fragment>
  );
}

/**
 * Days a worker submitted that the employer has not decided on yet.
 *
 * A worker can record the days they actually worked, but a submitted day only
 * counts towards their payment once the employer approves it — so a worker
 * cannot increase what they are owed on their own.
 */
function PendingWorkPanel({ applicants, onChanged }) {
  const [rows, setRows] = useState([]);
  const [msg, setMsg] = useState(null);

  const hired = (applicants || []).filter(a => a.status === "accepted" || a.status === "completed");

  const load = () => {
    if (hired.length === 0) { setRows([]); return; }
    Promise.all(hired.map(a =>
      API.workRecords(a.id)
         .then(d => ({ app: a, data: d }))
         .catch(() => null)))
      .then(all => {
        const pending = [];
        all.filter(Boolean).forEach(({ app, data }) => {
          (data.records || [])
            .filter(r => r.status === "pending")
            .forEach(r => pending.push({ record: r, app }));
        });
        setRows(pending);
      });
  };

  useEffect(() => { load(); }, [applicants.length]);

  const decide = async (row, approve) => {
    let note = "";
    if (!approve) {
      note = prompt("Why is this day not being approved? The worker will see this.") || "";
    }
    try {
      const r = await API.decideWorkRecord(row.record.id, approve, note);
      setMsg({ type:"success", text: r.message + (r.amount ? " The payment is now " + money(r.amount) + "." : "") });
      load();
      if (onChanged) onChanged();
    } catch (err) {
      setMsg({ type:"error", text: err.message });
    }
  };

  return (
    <div className="dash-panel">
      <h4>Work Submitted for Approval ({rows.length})</h4>
      <p style={{color:"var(--muted)",fontSize:13,marginTop:-4}}>
        Days your workers recorded themselves. They only count towards a payment once you approve them.
      </p>
      {msg && <div className={"form-msg " + msg.type}>{msg.text}</div>}
      {rows.length === 0
        ? <Empty icon="fa-clipboard-check" text="Nothing is waiting for your approval." />
        : <ul className="activity">{rows.map(row => (
            <li key={row.record.id} style={{flexWrap:"wrap",gap:12}}>
              <div className="a-ic ic-orange"><i className="fa-solid fa-calendar-day"></i></div>
              <div style={{flex:"1 1 260px"}}>
                <b>{row.app.workerName} — {Number(row.record.units).toFixed(2).replace(/\.00$/,"")} {row.record.unit}(s)</b>
                <small>
                  {row.app.jobTitle} · {fmtDate(row.record.workDate)} · {money(row.record.lineTotal)}
                  {row.record.notes && <React.Fragment><br />“{row.record.notes}”</React.Fragment>}
                </small>
              </div>
              <span className="when" style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
                <button className="btn btn-sm btn-green" onClick={() => decide(row, true)}>
                  <i className="fa-solid fa-check"></i> Approve
                </button>
                <button className="btn btn-sm btn-outline" onClick={() => decide(row, false)}>Reject</button>
              </span>
            </li>))}
          </ul>}
    </div>
  );
}

/* ============ DASHBOARD ============ */

/** Rating form shown for each completed job that still needs a review. */
function RateCard({ item, onDone }) {
  const [stars, setStars] = useState(5);
  const [comment, setComment] = useState("");
  const [busy, setBusy] = useState(false);

  const send = async () => {
    setBusy(true);
    try {
      await API.submitRating({ jobId: item.jobId, subjectId: item.subjectId, stars, comment });
      onDone();
    } catch (e) {
      alert(e.message);
      setBusy(false);
    }
  };

  return (
    <div className="dash-panel" style={{background:"var(--bg-soft,#f6f9fd)"}}>
      <h4 style={{marginBottom:6}}>Rate {item.subjectName}</h4>
      <p style={{color:"var(--muted)",fontSize:13,marginBottom:14}}>
        for <b style={{color:"var(--text)"}}>{item.jobTitle}</b> ({item.subjectRole})
      </p>
      <div style={{marginBottom:14}}>
        {[1,2,3,4,5].map(n => (
          <i key={n}
             className="fa-solid fa-star"
             onClick={() => setStars(n)}
             style={{fontSize:26,cursor:"pointer",marginRight:6,
                     color: n <= stars ? "#f59e0b" : "#d9dee8"}}></i>
        ))}
        <span style={{marginLeft:10,color:"var(--muted)",fontSize:13}}>{stars} of 5</span>
      </div>
      <div className="form-group">
        <label>Comment (optional)</label>
        <textarea rows="2" value={comment} onChange={e => setComment(e.target.value)}
                  placeholder="How did the work go?"></textarea>
      </div>
      <button className="btn btn-primary btn-sm" onClick={send} disabled={busy}>
        <i className="fa-solid fa-paper-plane"></i> {busy ? "Sending…" : "Submit Review"}
      </button>
    </div>
  );
}

/** The form employers use to publish a vacancy. */
/**
 * Posts a new job, or edits an existing one.
 *
 * Passing `job` switches the form into edit mode: the fields are filled from
 * that posting and saving calls PUT /api/jobs/{id} instead of POST. The same
 * form is used for both so the two can never drift apart.
 */
function PostJobForm({ onPosted, job, onCancel, projects }) {
  const editing = !!job;

  const [cats, setCats] = useState(["Construction","Agriculture","Manufacturing",
                                    "Transportation","Domestic Services","Cleaning","Security"]);
  useEffect(() => {
    API.categories()
      .then(list => { if (list && list.length) setCats(list.map(c => c.name)); })
      .catch(() => {});
  }, []);

  const blank = { title:"", category:"Construction", location:"Colombo", district:"",
                  pay:"", per:"day", urgent:false, description:"", requiredSkills:"",
                  workersNeeded:1, expectedUnits:1, startDate:"", endDate:"", projectId:"" };

  const dateOnly = (v) => (v ? String(v).slice(0, 10) : "");

  const fromJob = (j) => ({
    title: j.title || "", category: j.category || "Construction",
    location: j.location || "Colombo", district: j.district || "",
    pay: j.pay != null ? String(j.pay) : "", per: j.per || "day",
    urgent: !!j.urgent, description: j.description || "",
    requiredSkills: j.requiredSkills || "",
    workersNeeded: j.workersNeeded || 1, expectedUnits: j.expectedUnits || 1,
    startDate: dateOnly(j.startDate), endDate: dateOnly(j.endDate),
    projectId: j.projectId ? String(j.projectId) : ""
  });

  const [f, setF] = useState(editing ? fromJob(job) : blank);
  const [msg, setMsg] = useState(null);
  const [busy, setBusy] = useState(false);

  // Reload the fields when a different job is chosen for editing.
  useEffect(() => {
    setF(editing ? fromJob(job) : blank);
    setMsg(null);
  }, [job && job.id]);

  const set = (k) => (e) => setF(Object.assign({}, f, { [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value }));

  const submit = async (e) => {
    e.preventDefault();
    setMsg(null);
    if (!f.title.trim()) return setMsg({ type:"error", text:"Please enter a job title." });
    if (!Number(f.pay) || Number(f.pay) <= 0) return setMsg({ type:"error", text:"Please enter the daily pay amount." });
    setBusy(true);
    const payload = {
      title: f.title.trim(), category: f.category, location: f.location,
      district: (f.district || f.location).trim(),
      description: f.description.trim(), requiredSkills: f.requiredSkills.trim(),
      pay: Number(f.pay), per: f.per, urgent: f.urgent,
      workersNeeded: Number(f.workersNeeded) || 1,
      expectedUnits: Number(f.expectedUnits) || 1,
      startDate: f.startDate || null, endDate: f.endDate || null,
      projectId: f.projectId ? Number(f.projectId) : null
    };

    try {
      if (editing) {
        await API.updateJob(job.id, payload);
        setMsg({ type:"success", text:"Job updated. Anyone waiting on a decision has been told." });
        onPosted();
      } else {
        await API.postJob(payload);
        setMsg({ type:"success", text:"Job posted. It is now live for workers to see." });
        setF(blank);
        onPosted();
      }
    } catch (err) {
      setMsg({ type:"error", text: err.message });
    }
    setBusy(false);
  };

  return (
    <div className="dash-panel">
      <h4>{editing ? "Edit Job — " + job.title : "Post a New Job"}</h4>
      <form onSubmit={submit}>
        {msg && <div className={"form-msg " + msg.type}>{msg.text}</div>}
        {editing && job.hired > 0 && (
          <div className="form-msg info">
            <i className="fa-solid fa-circle-info" style={{marginRight:8}}></i>
            You have already hired {job.hired} worker(s) for this job, so the wage
            cannot be changed and the number of workers cannot go below {job.hired}.
          </div>
        )}
        <div className="form-group">
          <label>Job Title</label>
          <input value={f.title} onChange={set("title")} placeholder="e.g. Construction Helper" required />
        </div>
        <div className="form-row">
          <div className="form-group">
            <label>Category</label>
            <select value={f.category} onChange={set("category")}>
              {cats.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Location</label>
            <select value={f.location} onChange={set("location")}>
              {["Colombo","Gampaha","Kandy","Galle","Negombo","Kurunegala","Katunayake","Nuwara Eliya","Jaffna","Matara"].map(c =>
                <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
        </div>
        <div className="form-row">
          <div className="form-group">
            <label>Pay Amount (Rs.)</label>
            <input type="number" value={f.pay} onChange={set("pay")} placeholder="2500" min="1" required />
          </div>
          <div className="form-group">
            <label>Paid Per</label>
            <select value={f.per} onChange={set("per")}>
              <option value="day">Day</option>
              <option value="shift">Shift</option>
              <option value="hour">Hour</option>
            </select>
          </div>
        </div>
        <div className="form-group">
          <label htmlFor="j-skills">Skills Required</label>
          <input id="j-skills" value={f.requiredSkills} onChange={set("requiredSkills")}
                 placeholder="e.g. Masonry, Painting" />
          <small style={{color:"var(--muted)",fontSize:12,display:"block",marginTop:5}}>
            Separate with commas. Workers with these skills are told about your job.
          </small>
        </div>
        <div className="form-row">
          <div className="form-group">
            <label htmlFor="j-workers">Workers Needed</label>
            <input id="j-workers" type="number" min="1" max="500"
                   value={f.workersNeeded} onChange={set("workersNeeded")} />
          </div>
          <div className="form-group">
            <label htmlFor="j-units">Expected Days of Work</label>
            <input id="j-units" type="number" min="1" max="365"
                   value={f.expectedUnits} onChange={set("expectedUnits")} />
          </div>
        </div>
        <div className="form-row">
          <div className="form-group">
            <label htmlFor="j-start">Start Date (optional)</label>
            <input id="j-start" type="date" value={f.startDate} onChange={set("startDate")} />
          </div>
          <div className="form-group">
            <label htmlFor="j-end">End Date (optional)</label>
            <input id="j-end" type="date" value={f.endDate} onChange={set("endDate")} />
          </div>
        </div>
        <div className="form-group">
          <label htmlFor="j-desc">Description</label>
          <textarea id="j-desc" rows="3" value={f.description} onChange={set("description")}
                    placeholder="What the work involves, timings, anything the worker should know…"></textarea>
        </div>
        <div className="form-group">
          <label style={{display:"flex",alignItems:"center",gap:9,cursor:"pointer",fontWeight:500}}>
            <input type="checkbox" checked={f.urgent} onChange={set("urgent")}
                   style={{width:"auto",margin:0}} />
            Mark as urgent (shown at the top of the job list)
          </label>
        </div>
        {projects && projects.length > 0 && (
          <div className="form-group">
            <label htmlFor="j-project">Project (optional)</label>
            <select id="j-project" value={f.projectId} onChange={set("projectId")}>
              <option value="">Not part of a project</option>
              {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
            <small style={{color:"var(--muted)",fontSize:12,display:"block",marginTop:5}}>
              Grouping postings under a project lets you track hiring and cost across all of them.
            </small>
          </div>
        )}
        <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
          <button className="btn btn-primary" type="submit" disabled={busy}>
            <i className={"fa-solid " + (editing ? "fa-floppy-disk" : "fa-plus")}></i>{" "}
            {busy ? (editing ? "Saving…" : "Posting…") : (editing ? "Save Changes" : "Post Job")}
          </button>
          {editing && (
            <button className="btn btn-outline" type="button" onClick={onCancel} disabled={busy}>
              Cancel
            </button>
          )}
        </div>
      </form>
    </div>
  );
}

/** Edit-your-details panel, shared by every role. */
/* ============ CV UPLOAD (workers) ============ */
const CV_MAX_BYTES = 2 * 1024 * 1024;
const CV_EXTENSIONS = [".pdf", ".doc", ".docx"];

const fileSize = (bytes) => {
  const n = Number(bytes) || 0;
  return n >= 1048576 ? (n / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(n / 1024)) + " KB";
};

/**
 * Lets a worker upload, download, replace or remove their CV.
 *
 * It keeps its own copy of the CV's details rather than reloading the whole
 * profile after each change, so uploading a CV never wipes out profile edits
 * the worker has typed but not yet saved.
 */
function CvPanel({ profile }) {
  const [cv, setCv] = useState(profile.hasCv
    ? { fileName: profile.cvFileName, sizeBytes: profile.cvSizeBytes, uploadedAt: profile.cvUploadedAt }
    : null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState(null);
  const picker = React.useRef(null);

  const choose = () => { if (picker.current) picker.current.click(); };

  const onPicked = async (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";   // so choosing the same file again still triggers a change
    if (!file) return;

    // Checked here for a quick answer; the server checks all of this again.
    const name = file.name.toLowerCase();
    if (!CV_EXTENSIONS.some(ext => name.endsWith(ext))) {
      setMsg({ type:"error", text:"Please choose a PDF or Word document (.pdf, .doc or .docx)." });
      return;
    }
    if (file.size === 0) {
      setMsg({ type:"error", text:"That file is empty. Please choose another." });
      return;
    }
    if (file.size > CV_MAX_BYTES) {
      setMsg({ type:"error", text:"That file is too large. A CV can be up to 2 MB." });
      return;
    }

    setBusy(true); setMsg(null);
    try {
      const r = await API.uploadCv(file);
      setCv({ fileName: r.fileName, sizeBytes: r.sizeBytes, uploadedAt: r.uploadedAt });
      setMsg({ type:"success", text: r.message });
    } catch (err) {
      setMsg({ type:"error", text: err.message });
    }
    setBusy(false);
  };

  const remove = async () => {
    if (!confirm("Remove your CV? Employers you apply to from now on will not receive one.")) return;
    setBusy(true); setMsg(null);
    try {
      const r = await API.deleteCv();
      setCv(null);
      setMsg({ type:"success", text: r.message });
    } catch (err) {
      setMsg({ type:"error", text: err.message });
    }
    setBusy(false);
  };

  return (
    <div className="dash-panel" id="cv-panel">
      <h4>My CV</h4>
      {msg && <div className={"form-msg " + msg.type}>{msg.text}</div>}
      <p style={{color:"var(--muted)",fontSize:13.5,margin:"0 0 14px"}}>
        Upload your CV as a PDF or Word document, up to 2 MB. When you apply for a job,
        it is sent to that employer with your application and they can download it.
        Nobody else can see it.
      </p>

      <input ref={picker} type="file" id="cv-file" onChange={onPicked} style={{display:"none"}}
             accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" />

      {cv ? (
        <ul className="activity">
          <li style={{flexWrap:"wrap",gap:12}}>
            <div className="a-ic ic-blue"><i className="fa-solid fa-file-lines"></i></div>
            <div style={{flex:"1 1 220px"}}>
              <b style={{wordBreak:"break-word"}}>{cv.fileName}</b>
              <small>{fileSize(cv.sizeBytes)} · uploaded {fmtDate(cv.uploadedAt)}</small>
            </div>
            <span className="when" style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
              <button type="button" className="btn btn-sm btn-outline" disabled={busy}
                      onClick={() => downloadFile("/profile/cv", cv.fileName, "Could not download your CV.")}>
                <i className="fa-solid fa-download"></i> Download
              </button>
              <button type="button" className="btn btn-sm btn-outline" disabled={busy} onClick={choose}>
                <i className="fa-solid fa-upload"></i> {busy ? "Working…" : "Replace"}
              </button>
              <button type="button" className="btn btn-sm btn-outline" disabled={busy} onClick={remove}>
                <i className="fa-solid fa-trash"></i> Remove
              </button>
            </span>
          </li>
        </ul>
      ) : (
        <Empty icon="fa-file-arrow-up" text="You have not uploaded a CV yet."
               action={
                 <button type="button" className="btn btn-primary btn-sm" disabled={busy} onClick={choose}>
                   <i className="fa-solid fa-upload"></i> {busy ? "Uploading…" : "Upload CV"}
                 </button>} />
      )}
    </div>
  );
}

function ProfilePanel({ user }) {
  const [p, setP] = useState(null);
  const [msg, setMsg] = useState(null);
  const [busy, setBusy] = useState(false);
  const [loadError, setLoadError] = useState("");
  const [loadingProfile, setLoadingProfile] = useState(true);

  const load = async () => {
    setLoadingProfile(true);
    setLoadError("");
    try {
      const profile = await API.profile();
      if (!profile) throw new Error("The server returned an empty profile. Please sign in again.");
      setP(profile);
    } catch (err) {
      setLoadError(err?.message || "Unable to load your profile.");
    } finally {
      setLoadingProfile(false);
    }
  };
  useEffect(() => { load(); }, []);

  if (!p) return (
    <div className="dash-panel">
      {loadingProfile
        ? <Empty icon="fa-user" text="Loading your profile…" />
        : <div className="form-msg error" role="alert">
            <strong>Could not load your profile.</strong>
            <div style={{marginTop:6}}>{loadError}</div>
            <div style={{marginTop:12,display:"flex",gap:8,flexWrap:"wrap"}}>
              <button type="button" className="btn btn-primary btn-sm" onClick={load}>Try Again</button>
              {(loadError.includes("401") || loadError.toLowerCase().includes("sign in") || loadError.toLowerCase().includes("access has changed")) &&
                <button type="button" className="btn btn-outline btn-sm" onClick={() => { localStorage.removeItem("dw_token"); localStorage.removeItem("dw_user"); window.location.hash = "#/login"; window.location.reload(); }}>Sign In Again</button>}
            </div>
          </div>}
    </div>
  );

  const set = (k) => (e) => setP(Object.assign({}, p, { [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value }));

  const save = async (e) => {
    e.preventDefault();
    setBusy(true); setMsg(null);
    try {
      await API.updateProfile({
        name: p.name, phone: p.phone, skills: p.skills,
        location: p.location, district: p.district, bio: p.bio,
        experience: p.experience, experienceYears: Number(p.experienceYears) || 0,
        certifications: p.certifications, available: p.available
      });
      setMsg({ type:"success", text:"Your profile has been updated." });
    } catch (err) {
      setMsg({ type:"error", text: err.message });
    }
    setBusy(false);
  };

  return (
    <React.Fragment>
      <div className="dash-stats">
        <div className="dash-stat"><small>Average Rating</small>
          <b>{p.ratingCount ? p.averageRating : "—"}</b>
          <div style={{marginTop:4}}><Stars value={p.averageRating} /> <span style={{color:"var(--muted)",fontSize:12}}>({p.ratingCount})</span></div>
        </div>
        <div className="dash-stat"><small>Jobs Completed</small><b>{p.jobsCompleted}</b></div>
        <div className="dash-stat"><small>Total Earned</small><b>{money(p.totalEarned)}</b></div>
      </div>

      {p.workHistory && p.workHistory.length > 0 && (
        <div className="dash-panel">
          <h4>Work History</h4>
          <ul className="activity">
            {p.workHistory.map(h => (
              <li key={h.jobId + "-" + h.completedAt}>
                <div className="a-ic ic-green"><i className="fa-solid fa-circle-check"></i></div>
                <div><b>{h.jobTitle}</b><small>{h.category} · {h.location} · {h.employerName}</small></div>
                <span className="when">{fmtDate(h.completedAt)}</span>
              </li>))}
          </ul>
        </div>
      )}

      <div className="dash-panel">
        <h4>My Profile</h4>
        <form onSubmit={save}>
          {msg && <div className={"form-msg " + msg.type}>{msg.text}</div>}
          <div className="form-row">
            <div className="form-group"><label>Full Name</label>
              <input value={p.name} onChange={set("name")} required /></div>
            <div className="form-group"><label>Phone Number</label>
              <input value={p.phone} onChange={set("phone")} required /></div>
          </div>
          <div className="form-row">
            <div className="form-group"><label>Email (cannot be changed)</label>
              <input value={p.email} disabled style={{opacity:.6}} /></div>
            <div className="form-group"><label>Location</label>
              <input value={p.location || ""} onChange={set("location")} placeholder="e.g. Colombo" /></div>
          </div>
          <div className="form-group">
            <label htmlFor="p-skills">Skills</label>
            <input id="p-skills" value={p.skills || ""} onChange={set("skills")}
                   placeholder="e.g. Masonry, Painting, Driving" />
            <small style={{color:"var(--muted)",fontSize:12,display:"block",marginTop:5}}>
              Separate skills with commas. These are matched against job requirements
              to recommend work that suits you.
            </small>
          </div>
          <div className="form-row">
            <div className="form-group">
              <label htmlFor="p-district">District</label>
              <input id="p-district" value={p.district || ""} onChange={set("district")}
                     placeholder="e.g. Colombo" />
            </div>
            <div className="form-group">
              <label htmlFor="p-years">Years of Experience</label>
              <input id="p-years" type="number" min="0" max="60"
                     value={p.experienceYears || 0} onChange={set("experienceYears")} />
            </div>
          </div>
          <div className="form-group">
            <label htmlFor="p-exp">Work Experience</label>
            <textarea id="p-exp" rows="2" value={p.experience || ""} onChange={set("experience")}
                      placeholder="e.g. Eight years on housing and commercial sites"></textarea>
          </div>
          <div className="form-group">
            <label htmlFor="p-certs">Certifications &amp; Training</label>
            <input id="p-certs" value={p.certifications || ""} onChange={set("certifications")}
                   placeholder="e.g. NVQ Level 3 Masonry, Light vehicle licence" />
          </div>
          <div className="form-group">
            <label>About Me</label>
            <textarea rows="3" value={p.bio || ""} onChange={set("bio")}
                      placeholder="Your experience and when you are available…"></textarea>
          </div>
          {user.role === "worker" && (
            <div className="form-group">
              <label style={{display:"flex",alignItems:"center",gap:9,cursor:"pointer",fontWeight:500}}>
                <input type="checkbox" checked={!!p.available} onChange={set("available")} style={{width:"auto",margin:0}} />
                I am currently available for work
              </label>
            </div>
          )}
          <button className="btn btn-primary" type="submit" disabled={busy}>
            <i className="fa-solid fa-floppy-disk"></i> {busy ? "Saving…" : "Save Changes"}
          </button>
        </form>
      </div>

      {user.role === "worker" && <CvPanel profile={p} />}
    </React.Fragment>
  );
}

function Dashboard({ user, onLogout }) {
  const [tab, setTab] = useState("overview");
  const [tick, setTick] = useState(0);
  const refresh = () => setTick(t => t + 1);

  // worker data
  const [apps, setApps] = useState([]);
  const [payments, setPayments] = useState([]);
  const [ratings, setRatings] = useState([]);
  const [pendingRatings, setPendingRatings] = useState([]);
  const [notes, setNotes] = useState([]);

  // employer data
  const [eStats, setEStats] = useState(null);
  const [myJobs, setMyJobs] = useState([]);
  const [applicants, setApplicants] = useState([]);
  const [ePayments, setEPayments] = useState([]);

  // The job currently open in the edit form, or null when posting a new one.
  const [editingJob, setEditingJob] = useState(null);

  // Organization projects, used to file a posting under a project.
  const [projects, setProjects] = useState([]);

  useEffect(() => { if (!user) go("/login"); }, [user]);

  const isEmployer = user && (user.role === "employer" || user.role === "organization");
  const isOrganization = user && user.role === "organization";

  useEffect(() => {
    if (!user) return;
    API.myApps().then(d => setApps(d || [])).catch(() => setApps([]));
    API.myPayments().then(d => setPayments(d || [])).catch(() => setPayments([]));
    API.myRatings().then(d => setRatings(d || [])).catch(() => setRatings([]));
    API.pendingRatings().then(d => setPendingRatings(d || [])).catch(() => setPendingRatings([]));
    API.notifications().then(d => setNotes(d || [])).catch(() => setNotes([]));
    if (user.role === "employer" || user.role === "organization" || user.role === "admin") {
      API.employerStats().then(setEStats).catch(() => {});
      API.employerJobs().then(d => setMyJobs(d || [])).catch(() => setMyJobs([]));
      API.employerApplicants().then(d => setApplicants(d || [])).catch(() => setApplicants([]));
      API.employerPayments().then(d => setEPayments(d || [])).catch(() => setEPayments([]));
    }
    if (user.role === "organization") {
      API.projects().then(d => setProjects((d && d.projects) || [])).catch(() => setProjects([]));
    }
  }, [user, tick]);

  if (!user) return null;

  const earnings = payments.filter(p => p.status === "paid").reduce((s,p) => s + Number(p.amount), 0);
  const pendingPay = payments.filter(p => p.status !== "paid").reduce((s,p) => s + Number(p.amount), 0);
  const completed = apps.filter(a => a.status === "completed").length;
  const unread = notes.filter(n => !n.isRead).length;

  const setStatus = async (id, status) => {
    try { await API.setApplicationStatus(id, status); refresh(); }
    catch (e) { alert(e.message); }
  };
  const releasePay = async (id, who, outstanding) => {
    const raw = prompt(
      "How much has been paid to " + who + "?\n\n" +
      "Outstanding: " + money(outstanding) + "\n" +
      "Leave as is to record the full amount, or enter a smaller figure for a part payment.",
      String(outstanding));

    if (raw === null) return;

    const amount = Number(String(raw).replace(/[^0-9.]/g, ""));
    if (!amount || amount <= 0) { alert("Please enter a valid amount."); return; }

    const method = prompt("How was it paid? (cash, bank transfer, mobile)", "cash") || "";

    try {
      const r = await API.recordPayment(id, { amount, method });
      alert(r.message + (r.outstanding > 0 ? "\nStill outstanding: " + money(r.outstanding) : ""));
      refresh();
    } catch (e) { alert(e.message); }
  };

  // A worker records a day they worked. It is submitted for the employer to
  // approve, and does not count towards their payment until they do.
  const submitWorkDay = async (a) => {
    const units = prompt(
      "How many days/shifts did you work on \"" + a.jobTitle + "\"?\n\n" +
      "Your employer will review this before it is added to your payment.", "1");
    if (units === null) return;

    const n = Number(units);
    if (!n || n <= 0) { alert("Please enter a valid number."); return; }

    const note = prompt("Anything to add about this work? (optional)") || "";

    try {
      const r = await API.addWorkRecord(a.id, { units: n, notes: note });
      alert(r.message);
      refresh();
    } catch (e) { alert(e.message); }
  };

  // Worker confirms the money actually arrived.
  const confirmPay = async (id) => {
    try { await API.confirmPayment(id); refresh(); }
    catch (e) { alert(e.message); }
  };

  const disputePay = async (id) => {
    const note = prompt("What is wrong with this payment record?");
    if (note === null) return;
    try {
      const r = await API.disputePayment(id, note);
      alert(r.message);
      refresh();
    } catch (e) { alert(e.message); }
  };

  // Employer records a day of work against a hired assignment.
  const logWork = async (applicationId, workerName) => {
    const units = prompt("How many days/shifts did " + workerName + " work?\n\n" +
                         "Enter 1 for a single day.", "1");
    if (units === null) return;
    const n = Number(units);
    if (!n || n <= 0) { alert("Please enter a valid number."); return; }
    try {
      await API.addWorkRecord(applicationId, { units: n });
      alert("Work recorded. The total owed is calculated from these records when you verify the job.");
      refresh();
    } catch (e) { alert(e.message); }
  };
  const closeJob = async (id, title) => {
    if (!confirm('Close "' + title + '"? It will no longer appear in job searches.')) return;
    try { await API.closeJob(id); refresh(); }
    catch (e) { alert(e.message); }
  };
  const readAll = async () => {
    try { await API.markAllRead(); refresh(); } catch (e) { alert(e.message); }
  };

  // The recommendations panel can ask the dashboard to open the profile tab.
  useEffect(() => {
    const open = () => setTab("profile");
    window.addEventListener("dw-open-profile", open);
    return () => window.removeEventListener("dw-open-profile", open);
  }, []);

  const Item = ({ id, icon, label, badge }) => (
    <a className={tab === id ? "active" : ""}
       onClick={() => {
         // Leaving the form by the menu drops whatever was being edited, so
         // "Post a Job" always opens an empty form rather than a half-edited one.
         if (editingJob) setEditingJob(null);
         setTab(id);
       }}
       style={{cursor:"pointer"}}>
      <i className={"fa-solid " + icon}></i> {label}
      {badge > 0 && (
        <span style={{marginLeft:"auto",background:"var(--blue)",color:"#fff",fontSize:11,
                      fontWeight:700,borderRadius:99,padding:"1px 8px"}}>{badge}</span>
      )}
    </a>
  );

  return (
    <div className="dash">
      <aside className="dash-side">
        <Item id="overview" icon="fa-gauge" label="Overview" />
        {!isEmployer && user.role === "worker" &&
          <Item id="recommended" icon="fa-wand-magic-sparkles" label="Recommended" />}
        {isEmployer && <Item id="post" icon="fa-plus" label="Post a Job" />}
        {isOrganization && <Item id="projects" icon="fa-diagram-project" label="Projects" />}
        {isEmployer && <Item id="myjobs" icon="fa-briefcase" label="My Jobs" badge={myJobs.filter(j => j.status === "open").length} />}
        {isEmployer && <Item id="applicants" icon="fa-users" label="Applicants" badge={applicants.filter(a => a.status === "pending").length} />}
        {isEmployer && <Item id="worklog" icon="fa-calendar-check" label="Work Approvals" />}
        {!isEmployer && <Item id="applications" icon="fa-file-lines" label="My Applications" badge={apps.filter(a => a.status === "pending").length} />}
        <Item id="payments" icon="fa-money-check-dollar" label="Payments" />
        <Item id="reviews" icon="fa-star" label="Reviews" badge={pendingRatings.length} />
        <Item id="reports" icon="fa-chart-column" label="Reports" />
        {isEmployer && <Item id="verification" icon="fa-shield-halved" label="Verification" />}
        <Item id="notifications" icon="fa-bell" label="Notifications" badge={unread} />
        <Item id="profile" icon="fa-user" label="My Profile" />
        {!isEmployer && <Link to="/jobs"><i className="fa-solid fa-magnifying-glass"></i> Browse Jobs</Link>}
        {canSeePlans(user) && <Link to="/pricing"><i className="fa-solid fa-crown"></i> Plans</Link>}
        {user.role === "admin" && <Link to="/admin"><i className="fa-solid fa-user-shield"></i> Admin Panel</Link>}
        <a onClick={onLogout} style={{cursor:"pointer"}}><i className="fa-solid fa-right-from-bracket"></i> Logout</a>
      </aside>

      <main className="dash-main">
        <h2>Welcome, {user.name} <span style={{fontSize:14,color:"var(--muted)",fontWeight:500}}>({user.role})</span></h2>

        {/* ---------------- OVERVIEW ---------------- */}
        {tab === "overview" && (
          <React.Fragment>
            {isEmployer ? (
              <React.Fragment>
                <div className="dash-stats">
                  <div className="dash-stat"><small>Jobs Posted</small><b>{eStats ? eStats.myJobs : 0}</b></div>
                  <div className="dash-stat"><small>Applicants</small><b>{eStats ? eStats.applicants : 0}</b></div>
                  <div className="dash-stat"><small>Awaiting Review</small><b>{eStats ? eStats.pendingReview : 0}</b></div>
                </div>
                <div className="dash-stats">
                  <div className="dash-stat"><small>Currently Hired</small><b>{eStats ? eStats.hired : 0}</b></div>
                  <div className="dash-stat"><small>Payments Due</small><b>{money(eStats ? eStats.amountOwed : 0)}</b></div>
                  <div className="dash-stat"><small>Total Paid</small><b>{money(eStats ? eStats.amountPaid : 0)}</b></div>
                </div>
                <div className="dash-panel">
                  <h4>Latest Applicants</h4>
                  {applicants.length === 0
                    ? <Empty icon="fa-users" text="No applications yet. Post a job to start receiving applicants."
                             action={<button className="btn btn-primary btn-sm" onClick={() => setTab("post")}><i className="fa-solid fa-plus"></i> Post a Job</button>} />
                    : <ul className="activity">{applicants.slice(0,5).map(a => (
                        <li key={a.id}>
                          <div className="a-ic ic-blue"><i className="fa-solid fa-user"></i></div>
                          <div><b>{a.workerName}</b><small>{a.jobTitle} · <StatusBadge status={a.status} /></small></div>
                          <span className="when">{fmtDate(a.createdAt)}</span>
                        </li>))}
                      </ul>}
                </div>
              </React.Fragment>
            ) : (
              <React.Fragment>
                <div className="dash-stats">
                  <div className="dash-stat"><small>My Applications</small><b>{apps.length}</b></div>
                  <div className="dash-stat"><small>Jobs Completed</small><b>{completed}</b></div>
                  <div className="dash-stat"><small>Total Earnings</small><b>{money(earnings)}</b></div>
                </div>
                {user.role === "worker" && <RecommendedPanel user={user} onChanged={refresh} />}

                <div className="dash-panel">
                  <h4>Recent Applications</h4>
                  {apps.length === 0
                    ? <Empty icon="fa-file-lines" text="No applications yet."
                             action={<Link to="/jobs" className="btn btn-primary btn-sm"><i className="fa-solid fa-magnifying-glass"></i> Browse Jobs</Link>} />
                    : <ul className="activity">{apps.slice(0,5).map(a => (
                        <li key={a.id}>
                          <div className="a-ic ic-green"><i className="fa-solid fa-paper-plane"></i></div>
                          <div><b>{a.jobTitle}</b><small>{a.location} · {money(a.pay)} / day</small></div>
                          <span className="when"><StatusBadge status={a.status} /></span>
                        </li>))}
                      </ul>}
                </div>
                {pendingPay > 0 && (
                  <div className="dash-panel">
                    <h4>Payment Due to You</h4>
                    <p style={{fontSize:15,color:"var(--text)"}}>
                      <b style={{fontSize:22,color:"var(--orange,#f59e0b)"}}>{money(pendingPay)}</b> is recorded as owed and awaiting release by the employer.
                    </p>
                  </div>
                )}
              </React.Fragment>
            )}
          </React.Fragment>
        )}

        {/* ---------------- RECOMMENDED ---------------- */}
        {tab === "recommended" && !isEmployer && (
          <RecommendedPanel user={user} onChanged={refresh} />
        )}

        {/* ---------------- REPORTS ---------------- */}
        {tab === "reports" && <ReportsPanel user={user} />}

        {/* ---------------- VERIFICATION ---------------- */}
        {tab === "verification" && isEmployer && <VerificationPanel />}

        {/* ---------------- POST A JOB ---------------- */}
        {tab === "projects" && isOrganization && <ProjectsPanel onChanged={refresh} />}

        {tab === "worklog" && isEmployer && (
          <PendingWorkPanel applicants={applicants} onChanged={refresh} />
        )}

        {tab === "post" && isEmployer && (
          <PostJobForm
            job={editingJob}
            projects={projects}
            onCancel={() => { setEditingJob(null); setTab("myjobs"); }}
            onPosted={() => {
              refresh();
              if (editingJob) { setEditingJob(null); setTab("myjobs"); }
            }} />
        )}

        {/* ---------------- MY JOBS ---------------- */}
        {tab === "myjobs" && isEmployer && (
          <div className="dash-panel">
            <h4>My Jobs ({myJobs.length})</h4>
            {myJobs.length === 0
              ? <Empty icon="fa-briefcase" text="You have not posted any jobs yet."
                       action={<button className="btn btn-primary btn-sm" onClick={() => setTab("post")}><i className="fa-solid fa-plus"></i> Post a Job</button>} />
              : <div style={{overflowX:"auto"}}>
                  <table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}>
                    <thead><tr style={{background:"var(--bg-soft,#f6f9fd)"}}>
                      <th style={{padding:12,textAlign:"left"}}>Title</th>
                      <th style={{padding:12,textAlign:"left"}}>Category</th>
                      <th style={{padding:12,textAlign:"left"}}>Location</th>
                      <th style={{padding:12,textAlign:"left"}}>Pay</th>
                      <th style={{padding:12,textAlign:"left"}}>Applicants</th>
                      <th style={{padding:12,textAlign:"left"}}>Status</th>
                      <th style={{padding:12}}></th>
                    </tr></thead>
                    <tbody>{myJobs.map(j => (
                      <tr key={j.id} style={{borderBottom:"1px solid var(--border,#e2e8f0)"}}>
                        <td style={{padding:12,fontWeight:600,color:"var(--navy,#0b2447)"}}>{j.title}</td>
                        <td style={{padding:12,color:"var(--muted)"}}>{j.category}</td>
                        <td style={{padding:12,color:"var(--muted)"}}>{j.location}</td>
                        <td style={{padding:12,color:"var(--green,#16a34a)",fontWeight:700}}>{money(j.pay)}</td>
                        <td style={{padding:12}}>{j.applications} {j.pending > 0 && <span style={{color:"var(--blue)",fontWeight:700}}>({j.pending} new)</span>}</td>
                        <td style={{padding:12}}><StatusBadge status={j.status} /></td>
                        <td style={{padding:12}}>
                          {j.status === "open" && (
                            <span style={{display:"flex",gap:8,justifyContent:"flex-end",flexWrap:"wrap"}}>
                              <button className="btn btn-sm btn-outline"
                                      onClick={() => { setEditingJob(j); setTab("post"); }}>
                                <i className="fa-solid fa-pen"></i> Edit
                              </button>
                              <button className="btn btn-sm btn-outline" onClick={() => closeJob(j.id, j.title)}>Close</button>
                            </span>
                          )}
                        </td>
                      </tr>))}
                    </tbody>
                  </table>
                </div>}
          </div>
        )}

        {/* ---------------- APPLICANTS ---------------- */}
        {tab === "applicants" && isEmployer && (
          <div className="dash-panel">
            <h4>Applicants ({applicants.length})</h4>
            {applicants.length === 0
              ? <Empty icon="fa-users" text="Nobody has applied to your jobs yet." />
              : <ul className="activity">{applicants.map(a => (
                  <li key={a.id} style={{alignItems:"flex-start",flexWrap:"wrap",gap:12}}>
                    <div className="a-ic ic-blue"><i className="fa-solid fa-user"></i></div>
                    <div style={{flex:"1 1 240px"}}>
                      <b>{a.workerName} {a.workerRating > 0 && <Stars value={a.workerRating} size={12} />}</b>
                      <small>
                        Applied for <b style={{color:"var(--text)"}}>{a.jobTitle}</b> · {fmtDate(a.createdAt)}<br />
                        <i className="fa-solid fa-phone" style={{marginRight:5}}></i>{a.workerPhone}
                        <span style={{margin:"0 8px"}}>·</span>
                        <i className="fa-solid fa-envelope" style={{marginRight:5}}></i>{a.workerEmail}
                        {a.workerSkills && <React.Fragment><br /><i className="fa-solid fa-screwdriver-wrench" style={{marginRight:5}}></i>{a.workerSkills}</React.Fragment>}
                      </small>
                    </div>
                    <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginLeft:"auto"}}>
                      <StatusBadge status={a.status} />
                      {a.workerHasCv && (
                        <button className="btn btn-sm btn-outline" title={a.workerCvFileName}
                                onClick={() => downloadFile("/profile/" + a.workerId + "/cv",
                                                            a.workerCvFileName || "cv", "Could not download the CV.")}>
                          <i className="fa-solid fa-file-arrow-down"></i> CV
                        </button>
                      )}
                      {/* Hiring and declining stay available after shortlisting.
                          The server allows pending -> accepted/rejected AND
                          shortlisted -> accepted/rejected, so offering these
                          only while pending left a shortlisted applicant stuck
                          with no way forward. */}
                      {(a.status === "pending" || a.status === "shortlisted") && (
                        <React.Fragment>
                          <button className="btn btn-sm btn-primary" onClick={() => setStatus(a.id, "accepted")}>
                            <i className="fa-solid fa-check"></i> Hire
                          </button>
                          <button className="btn btn-sm btn-outline" onClick={() => setStatus(a.id, "rejected")}>
                            Decline
                          </button>
                        </React.Fragment>
                      )}
                      {a.status === "pending" && (
                        <button className="btn btn-sm btn-outline" onClick={() => setStatus(a.id, "shortlisted")}>
                          Shortlist
                        </button>
                      )}
                      {a.status === "accepted" && (
                        <React.Fragment>
                          <button className="btn btn-sm btn-outline" onClick={() => logWork(a.id, a.workerName)}>
                            <i className="fa-solid fa-calendar-plus"></i> Log Work Day
                          </button>
                          <button className="btn btn-sm btn-green" onClick={() => setStatus(a.id, "completed")}>
                            <i className="fa-solid fa-clipboard-check"></i> Verify Work Done
                          </button>
                        </React.Fragment>
                      )}
                    </div>
                  </li>))}
                </ul>}
          </div>
        )}

        {/* ---------------- MY APPLICATIONS (worker) ---------------- */}
        {tab === "applications" && !isEmployer && (
          <div className="dash-panel">
            <h4>My Applications ({apps.length})</h4>
            {apps.length === 0
              ? <Empty icon="fa-file-lines" text="You have not applied for any jobs yet."
                       action={<Link to="/jobs" className="btn btn-primary btn-sm"><i className="fa-solid fa-magnifying-glass"></i> Browse Jobs</Link>} />
              : <ul className="activity">{apps.map(a => (
                  <li key={a.id} style={{flexWrap:"wrap",gap:12}}>
                    <div className="a-ic ic-green"><i className="fa-solid fa-paper-plane"></i></div>
                    <div style={{flex:"1 1 240px"}}>
                      <b>{a.jobTitle}</b>
                      <small>{a.location} · {money(a.pay)} / day · applied {fmtDate(a.createdAt)}</small>
                    </div>
                    <span className="when" style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
                      <StatusBadge status={a.status} />
                      {a.status === "accepted" && (
                        <button className="btn btn-sm btn-outline" onClick={() => submitWorkDay(a)}>
                          <i className="fa-solid fa-calendar-plus"></i> Record a Work Day
                        </button>
                      )}
                    </span>
                  </li>))}
                </ul>}
          </div>
        )}

        {/* ---------------- PAYMENTS ---------------- */}
        {tab === "payments" && (
          isEmployer ? (
            <div className="dash-panel">
              <h4>Payments to Workers ({ePayments.length})</h4>
              {ePayments.length === 0
                ? <Empty icon="fa-money-check-dollar" text="No payments yet. A payment is raised automatically when you verify completed work." />
                : <ul className="activity">{ePayments.map(p => (
                    <li key={p.id}>
                      <div className={"a-ic " + (p.status === "paid" ? "ic-green" : "ic-orange")}>
                        <i className="fa-solid fa-money-bill-wave"></i>
                      </div>
                      <div>
                        <b>{money(p.amount)} to {p.workerName}</b>
                        <small>
                          {p.jobTitle} · {Number(p.unitsWorked || 1).toFixed(0)} {p.rateUnit}(s) at {money(p.agreedRate)}
                          {p.amountPaid > 0 && p.outstanding > 0 &&
                            <React.Fragment><br />{money(p.amountPaid)} paid · {money(p.outstanding)} outstanding
                              {p.awaitingConfirmation > 0
                                ? " · " + money(p.awaitingConfirmation) + " awaiting the worker's confirmation"
                                : " · confirmed by the worker"}
                            </React.Fragment>}
                          {p.status === "paid" &&
                            <React.Fragment><br />Paid {fmtDate(p.paidAt)}
                              {p.workerConfirmed
                                ? " · confirmed by worker"
                                : (p.confirmedAmount > 0
                                    ? " · worker confirmed " + money(p.confirmedAmount) +
                                      ", " + money(p.awaitingConfirmation) + " not yet confirmed"
                                    : " · awaiting worker confirmation")}
                            </React.Fragment>}
                        </small>
                      </div>
                      <span className="when" style={{display:"flex",gap:8,alignItems:"center"}}>
                        <StatusBadge status={p.status} />
                        {p.status !== "paid" &&
                          <button className="btn btn-sm btn-green"
                                  onClick={() => releasePay(p.id, p.workerName, p.outstanding)}>
                            <i className="fa-solid fa-check"></i> Record Payment
                          </button>}
                      </span>
                    </li>))}
                  </ul>}
            </div>
          ) : (
            <React.Fragment>
              <div className="dash-stats">
                <div className="dash-stat"><small>Total Received</small><b>{money(earnings)}</b></div>
                <div className="dash-stat"><small>Awaiting Payment</small><b>{money(pendingPay)}</b></div>
                <div className="dash-stat"><small>Payment Records</small><b>{payments.length}</b></div>
              </div>
              <div className="dash-panel">
                <h4>Payment History</h4>
                {payments.length === 0
                  ? <Empty icon="fa-money-check-dollar" text="No payments yet. Payments appear here once your completed work is verified." />
                  : <ul className="activity">{payments.map(p => (
                      <li key={p.id}>
                        <div className={"a-ic " + (p.status === "paid" ? "ic-green" : "ic-orange")}>
                          <i className="fa-solid fa-money-bill-wave"></i>
                        </div>
                        <div>
                          <b>{money(p.amount)} — {p.jobTitle}</b>
                          <small>
                            {Number(p.unitsWorked || 1).toFixed(0)} {p.rateUnit}(s) at {money(p.agreedRate)}
                            {p.amountPaid > 0 && p.outstanding > 0 &&
                              <React.Fragment><br />{money(p.amountPaid)} received · {money(p.outstanding)} still owed</React.Fragment>}
                            {p.status === "paid" &&
                              <React.Fragment><br />Recorded as paid on {fmtDate(p.paidAt)}</React.Fragment>}
                            {p.workerConfirmed &&
                              <React.Fragment><br /><span style={{color:"var(--green,#16a34a)"}}>
                                {p.status === "paid"
                                  ? "You confirmed receiving this."
                                  : "You confirmed receiving " + money(p.confirmedAmount) + " so far."}
                              </span></React.Fragment>}
                            {!p.workerConfirmed && p.confirmedAmount > 0 && (
                              <React.Fragment><br /><span style={{color:"var(--orange,#f59e0b)"}}>
                                You confirmed {money(p.confirmedAmount)}. A further {money(p.awaitingConfirmation)} has
                                since been recorded — please confirm it.
                              </span></React.Fragment>)}
                          </small>
                        </div>
                        <span className="when" style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
                          <StatusBadge status={p.status} />
                          {p.amountPaid > 0 && !p.workerConfirmed && (
                            <React.Fragment>
                              <button className="btn btn-sm btn-green" onClick={() => confirmPay(p.id)}>
                                <i className="fa-solid fa-check"></i>{" "}
                                {p.confirmedAmount > 0
                                  ? "Confirm " + money(p.awaitingConfirmation) + " More"
                                  : "Confirm Received"}
                              </button>
                              <button className="btn btn-sm btn-outline" onClick={() => disputePay(p.id)}>
                                Report a problem
                              </button>
                            </React.Fragment>
                          )}
                        </span>
                      </li>))}
                    </ul>}
              </div>
            </React.Fragment>
          )
        )}

        {/* ---------------- REVIEWS ---------------- */}
        {tab === "reviews" && (
          <React.Fragment>
            {pendingRatings.length > 0 && (
              <React.Fragment>
                <div className="dash-panel" style={{marginBottom:16}}>
                  <h4>Reviews You Can Leave</h4>
                  <p style={{color:"var(--muted)",fontSize:13.5,margin:0}}>
                    These jobs are finished. Leaving a review helps the other side build their reputation.
                  </p>
                </div>
                {pendingRatings.map(item => (
                  <RateCard key={item.jobId + "-" + item.subjectId} item={item} onDone={refresh} />
                ))}
              </React.Fragment>
            )}

            <div className="dash-panel">
              <h4>Reviews About Me ({ratings.length})</h4>
              {ratings.length === 0
                ? <Empty icon="fa-star" text="No reviews yet. Complete a job to start building your reputation." />
                : <ul className="activity">{ratings.map(r => (
                    <li key={r.id} style={{alignItems:"flex-start"}}>
                      <div className="a-ic ic-orange"><i className="fa-solid fa-star"></i></div>
                      <div>
                        <b><Stars value={r.stars} /> <span style={{marginLeft:6}}>{r.authorName}</span></b>
                        <small>
                          {r.jobTitle}
                          {r.comment && <React.Fragment><br /><span style={{fontStyle:"italic",color:"var(--text)"}}>"{r.comment}"</span></React.Fragment>}
                        </small>
                      </div>
                      <span className="when">{fmtDate(r.createdAt)}</span>
                    </li>))}
                  </ul>}
            </div>
          </React.Fragment>
        )}

        {/* ---------------- NOTIFICATIONS ---------------- */}
        {tab === "notifications" && (
          <div className="dash-panel">
            <h4 style={{display:"flex",alignItems:"center",gap:12}}>
              Notifications
              {unread > 0 && (
                <button className="btn btn-sm btn-outline" style={{marginLeft:"auto"}} onClick={readAll}>
                  <i className="fa-solid fa-check-double"></i> Mark all as read
                </button>
              )}
            </h4>
            {notes.length === 0
              ? <Empty icon="fa-bell" text="No notifications yet. You will be alerted here about applications, hiring and payments." />
              : <ul className="activity">{notes.map(n => {
                  const tint = { application:"ic-blue", accepted:"ic-green", hired:"ic-green",
                                 rejected:"ic-pink", completed:"ic-green", payment:"ic-green",
                                 rating:"ic-orange" }[n.type] || "ic-navy";
                  const icon = { application:"fa-user-plus", accepted:"fa-circle-check", hired:"fa-circle-check",
                                 rejected:"fa-circle-xmark", completed:"fa-clipboard-check",
                                 payment:"fa-money-bill-wave", rating:"fa-star" }[n.type] || "fa-bell";
                  return (
                    <li key={n.id} style={{opacity: n.isRead ? .62 : 1}}>
                      <div className={"a-ic " + tint}><i className={"fa-solid " + icon}></i></div>
                      <div>
                        <b>{n.title}{!n.isRead && <span style={{marginLeft:8,width:7,height:7,borderRadius:"50%",background:"var(--blue)",display:"inline-block"}}></span>}</b>
                        <small>{n.message}</small>
                      </div>
                      <span className="when">{fmtDate(n.createdAt)}</span>
                    </li>);
                })}
                </ul>}
          </div>
        )}

        {/* ---------------- PROFILE ---------------- */}
        {tab === "profile" && <ProfilePanel user={user} />}
      </main>
    </div>
  );
}

/* ============ ADMIN: VERIFICATION QUEUE ============ */

function VerificationQueue({ onChanged }) {
  const [rows, setRows] = useState([]);
  const [filter, setFilter] = useState("pending");
  const [loading, setLoading] = useState(true);

  const load = () => {
    setLoading(true);
    API.adminVerifications(filter)
      .then(d => setRows(d || []))
      .catch(() => setRows([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [filter]);

  const decide = async (userId, approve, name) => {
    let note = "";
    if (!approve) {
      note = prompt('Why is "' + name + '" being rejected? The applicant will see this.') || "";
      if (note.trim().length < 5) {
        alert("Please give a reason of at least 5 characters.");
        return;
      }
    }
    try {
      await API.adminDecideVerification(userId, approve, note);
      load();
      if (onChanged) onChanged();
    } catch (e) { alert(e.message); }
  };

  return (
    <div className="dash-panel">
      <h4 style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
        Organization Verification
        <select value={filter} onChange={e => setFilter(e.target.value)}
                style={{marginLeft:"auto",padding:"6px 10px",borderRadius:7,
                        border:"1.5px solid var(--border,#e2e8f0)",fontSize:13}}>
          <option value="pending">Pending</option>
          <option value="verified">Verified</option>
          <option value="rejected">Rejected</option>
          <option value="all">All requests</option>
        </select>
      </h4>

      {loading
        ? <Empty icon="fa-shield-halved" text="Loading requests…" />
        : rows.length === 0
          ? <Empty icon="fa-shield-halved" text={"No " + filter + " verification requests."} />
          : <ul className="activity">
              {rows.map(r => (
                <li key={r.userId} style={{alignItems:"flex-start",flexWrap:"wrap",gap:12}}>
                  <div className="a-ic ic-purple"><i className="fa-solid fa-building"></i></div>
                  <div style={{flex:"1 1 260px"}}>
                    <b>{r.organizationName || r.name}</b>
                    <small>
                      {r.email} · {r.phone}<br />
                      Registration: {r.registrationNumber || "not given"}<br />
                      {r.organizationAddress}
                      {r.notes && <React.Fragment><br /><i>"{r.notes}"</i></React.Fragment>}
                      {r.decisionNote && <React.Fragment><br />
                        <span style={{color:"var(--red,#dc2626)"}}>Decision: {r.decisionNote}</span>
                      </React.Fragment>}
                    </small>
                  </div>
                  <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginLeft:"auto"}}>
                    <StatusBadge status={r.status} />
                    <span style={{fontSize:12,color:"var(--muted)"}}>{fmtDate(r.requestedAt)}</span>
                    {r.status === "pending" && (
                      <React.Fragment>
                        <button className="btn btn-sm btn-green" onClick={() => decide(r.userId, true, r.organizationName)}>
                          <i className="fa-solid fa-check"></i> Approve
                        </button>
                        <button className="btn btn-sm btn-outline" onClick={() => decide(r.userId, false, r.organizationName)}>
                          Reject
                        </button>
                      </React.Fragment>
                    )}
                  </div>
                </li>))}
            </ul>}
    </div>
  );
}

/* ============ ADMIN: CATEGORY MANAGEMENT ============ */

function CategoryManager() {
  const [rows, setRows] = useState([]);
  const [form, setForm] = useState({ name:"", description:"", icon:"fa-briefcase", sortOrder:0 });
  const [msg, setMsg] = useState(null);

  const load = () => API.allCategories().then(d => setRows(d || [])).catch(() => setRows([]));
  useEffect(() => { load(); }, []);

  const set = (k) => (e) => setForm(Object.assign({}, form, { [k]: e.target.value }));

  const add = async (e) => {
    e.preventDefault();
    setMsg(null);
    try {
      await API.createCategory(Object.assign({}, form, { sortOrder: Number(form.sortOrder) || 0 }));
      setForm({ name:"", description:"", icon:"fa-briefcase", sortOrder:0 });
      setMsg({ type:"success", text:"Category added." });
      load();
    } catch (err) { setMsg({ type:"error", text: err.message }); }
  };

  const toggle = async (c) => {
    try {
      await API.updateCategory(c.id, {
        name: c.name, description: c.description, icon: c.icon,
        sortOrder: c.sortOrder, isActive: !c.isActive
      });
      load();
    } catch (e) { alert(e.message); }
  };

  const remove = async (c) => {
    if (!confirm('Delete the category "' + c.name + '"?')) return;
    try {
      const r = await API.deleteCategory(c.id);
      alert(r.message);
      load();
    } catch (e) { alert(e.message); }
  };

  return (
    <React.Fragment>
      <div className="dash-panel">
        <h4>Job Categories ({rows.length})</h4>
        {rows.length === 0
          ? <Empty icon="fa-layer-group" text="No categories defined yet." />
          : <div className="admin-table">
              <table>
                <thead><tr>
                  <th>Name</th><th>Description</th><th>Open Jobs</th><th>Status</th><th></th>
                </tr></thead>
                <tbody>
                  {rows.map(c => (
                    <tr key={c.id}>
                      <td className="name">
                        <i className={"fa-solid " + c.icon} style={{marginRight:8,color:"var(--blue)"}}></i>
                        {c.name}
                      </td>
                      <td>{c.description}</td>
                      <td>{c.openJobs}</td>
                      <td><StatusBadge status={c.isActive ? "open" : "closed"} /></td>
                      <td style={{whiteSpace:"nowrap"}}>
                        <button className="btn btn-sm btn-outline" onClick={() => toggle(c)}>
                          {c.isActive ? "Hide" : "Show"}
                        </button>
                        <button className="btn btn-sm btn-danger" style={{marginLeft:6}}
                                onClick={() => remove(c)}>
                          <i className="fa-solid fa-trash"></i>
                        </button>
                      </td>
                    </tr>))}
                </tbody>
              </table>
            </div>}
      </div>

      <div className="dash-panel">
        <h4>Add a Category</h4>
        <form onSubmit={add}>
          {msg && <div className={"form-msg " + msg.type}>{msg.text}</div>}
          <div className="form-row">
            <div className="form-group">
              <label htmlFor="cat-name">Name</label>
              <input id="cat-name" value={form.name} onChange={set("name")} required />
            </div>
            <div className="form-group">
              <label htmlFor="cat-icon">Icon</label>
              <input id="cat-icon" value={form.icon} onChange={set("icon")}
                     placeholder="fa-briefcase" />
            </div>
          </div>
          <div className="form-group">
            <label htmlFor="cat-desc">Description</label>
            <input id="cat-desc" value={form.description} onChange={set("description")} />
          </div>
          <button className="btn btn-primary" type="submit">
            <i className="fa-solid fa-plus"></i> Add Category
          </button>
        </form>
      </div>
    </React.Fragment>
  );
}

/* ============ ADMIN: CONTACT MESSAGES ============ */

function MessageInbox() {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = () => {
    setLoading(true);
    API.adminMessages().then(d => setRows(d || [])).catch(() => setRows([])).finally(() => setLoading(false));
  };
  useEffect(() => { load(); }, []);

  const mark = async (id, status) => {
    try { await API.adminUpdateMessage(id, status); load(); }
    catch (e) { alert(e.message); }
  };

  return (
    <div className="dash-panel">
      <h4>Contact Messages ({rows.length})</h4>
      {loading
        ? <Empty icon="fa-envelope" text="Loading messages…" />
        : rows.length === 0
          ? <Empty icon="fa-envelope" text="No messages have been sent through the contact form yet." />
          : <ul className="activity">
              {rows.map(m => (
                <li key={m.id} style={{alignItems:"flex-start",flexWrap:"wrap",gap:12,
                                       opacity: m.status === "answered" ? .65 : 1}}>
                  <div className={"a-ic " + (m.status === "new" ? "ic-blue" : "ic-navy")}>
                    <i className="fa-solid fa-envelope"></i>
                  </div>
                  <div style={{flex:"1 1 280px"}}>
                    <b>{m.subject}</b>
                    <small>
                      From {m.name} &lt;{m.email}&gt;<br />
                      {m.message}
                    </small>
                  </div>
                  <div style={{display:"flex",gap:8,alignItems:"center",marginLeft:"auto",flexWrap:"wrap"}}>
                    <StatusBadge status={m.status === "new" ? "pending" : m.status === "answered" ? "completed" : "accepted"} />
                    <span style={{fontSize:12,color:"var(--muted)"}}>{fmtDate(m.createdAt)}</span>
                    {m.status !== "answered" && (
                      <button className="btn btn-sm btn-outline" onClick={() => mark(m.id, "answered")}>
                        Mark answered
                      </button>
                    )}
                  </div>
                </li>))}
            </ul>}
    </div>
  );
}

