/* ============ ADMIN ============ */
const ROLES = ["worker","employer","organization","admin"];

function Admin({ user, onLogout }) {
  const [tab, setTab] = useState("overview");
  const [tick, setTick] = useState(0);
  const refresh = () => setTick(t => t + 1);

  const [stats, setStats] = useState({ totalUsers:0, workers:0, employers:0, totalJobs:0, openJobs:0, applications:0, payments:0, paidAmount:0 });
  const [users, setUsers] = useState([]);
  const [jobs, setJobs] = useState([]);

  useEffect(() => { if (!user) go("/login"); else if (user.role !== "admin") go("/dashboard"); }, [user]);

  useEffect(() => {
    if (!user || user.role !== "admin") return;
    API.adminStats().then(d => setStats(d || {})).catch(() => {});
    API.adminUsers().then(d => setUsers(d || [])).catch(() => {});
    API.adminJobs().then(d => setJobs(d || [])).catch(() => {});
  }, [user, tick]);

  if (!user || user.role !== "admin") return null;

  const changeRole = async (id, role) => { try { await API.adminChangeRole(id, role); refresh(); } catch (e) { alert(e.message); } };
  const delUser = async (id, name) => { if (confirm('Delete user "' + name + '"? This also removes their applications.')) { try { await API.adminDeleteUser(id); refresh(); } catch (e) { alert(e.message); } } };
  const delJob = async (id, title) => { if (confirm('Delete job "' + title + '"?')) { try { await API.adminDeleteJob(id); refresh(); } catch (e) { alert(e.message); } } };

  const roleBadge = (r) => {
    const colors = { admin:"#dc2626", employer:"var(--blue)", organization:"#8b5cf6", worker:"var(--green)" };
    return <span className="jc-badge" style={{background:"#f1f5f9",color:colors[r] || "var(--muted)"}}>{r}</span>;
  };
  const th = { padding:12, textAlign:"left" };
  const td = { padding:12, color:"var(--muted)" };

  return (
    <div className="dash">
      <aside className="dash-side">
        <a className={tab === "overview" ? "active" : ""} onClick={() => setTab("overview")} style={{cursor:"pointer"}}><i className="fa-solid fa-gauge"></i> Overview</a>
        <a className={tab === "users" ? "active" : ""} onClick={() => setTab("users")} style={{cursor:"pointer"}}><i className="fa-solid fa-users"></i> Manage Users</a>
        <a className={tab === "jobs" ? "active" : ""} onClick={() => setTab("jobs")} style={{cursor:"pointer"}}><i className="fa-solid fa-briefcase"></i> Manage Jobs</a>
        <a className={tab === "verify" ? "active" : ""} onClick={() => setTab("verify")} style={{cursor:"pointer"}}>
          <i className="fa-solid fa-shield-halved"></i> Verification
          {stats.pendingVerifications > 0 && (
            <span style={{marginLeft:"auto",background:"var(--blue)",color:"#fff",fontSize:11,
                          fontWeight:700,borderRadius:99,padding:"1px 8px"}}>
              {stats.pendingVerifications}
            </span>)}
        </a>
        <a className={tab === "categories" ? "active" : ""} onClick={() => setTab("categories")} style={{cursor:"pointer"}}><i className="fa-solid fa-layer-group"></i> Categories</a>
        <a className={tab === "messages" ? "active" : ""} onClick={() => setTab("messages")} style={{cursor:"pointer"}}>
          <i className="fa-solid fa-envelope"></i> Messages
          {stats.newMessages > 0 && (
            <span style={{marginLeft:"auto",background:"var(--blue)",color:"#fff",fontSize:11,
                          fontWeight:700,borderRadius:99,padding:"1px 8px"}}>
              {stats.newMessages}
            </span>)}
        </a>
        <a className={tab === "reports" ? "active" : ""} onClick={() => setTab("reports")} style={{cursor:"pointer"}}><i className="fa-solid fa-chart-column"></i> Reports</a>
        <Link to="/"><i className="fa-solid fa-house"></i> Back to Site</Link>
        <a onClick={onLogout} style={{cursor:"pointer"}}><i className="fa-solid fa-right-from-bracket"></i> Logout</a>
      </aside>
      <main className="dash-main">
        <h2><i className="fa-solid fa-user-shield" style={{color:"#dc2626",marginRight:10}}></i>Admin Panel
          <span style={{fontSize:14,color:"var(--muted)",fontWeight:500}}> — {user.name}</span></h2>

        {tab === "overview" && (
          <React.Fragment>
            <div className="dash-stats">
              <div className="dash-stat"><small>Total Users</small><b>{stats.totalUsers}</b></div>
              <div className="dash-stat"><small>Workers</small><b>{stats.workers}</b></div>
              <div className="dash-stat"><small>Employers / Orgs</small><b>{stats.employers}</b></div>
            </div>
            <div className="dash-stats">
              <div className="dash-stat"><small>Total Jobs</small><b>{stats.totalJobs}</b></div>
              <div className="dash-stat"><small>Open Jobs</small><b>{stats.openJobs}</b></div>
              <div className="dash-stat"><small>Applications</small><b>{stats.applications}</b></div>
            </div>
            <div className="dash-panel">
              <h4>Payments</h4>
              <p style={{fontSize:15}}>
                <b style={{fontSize:24,color:"var(--green)"}}>Rs. {Number(stats.paidAmount || 0).toLocaleString()}</b> paid across {stats.payments || 0} payment records.
              </p>
            </div>
            <div className="dash-panel">
              <h4>Recent Registrations</h4>
              <ul className="activity">{users.slice(0,5).map(u => (
                <li key={u.id}>
                  <div className="a-ic ic-blue"><i className="fa-solid fa-user"></i></div>
                  <div><b>{u.name}</b><small>{u.email} · {u.role}</small></div>
                  <span className="when">{new Date(u.createdAt).toLocaleDateString()}</span>
                </li>))}
              </ul>
            </div>
          </React.Fragment>)}

        {tab === "verify" && <VerificationQueue onChanged={refresh} />}
        {tab === "categories" && <CategoryManager />}
        {tab === "messages" && <MessageInbox />}
        {tab === "reports" && <AdminReport />}

        {tab === "users" && (
          <div className="dash-panel">
            <h4>All Users ({users.length})</h4>
            <div style={{overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}>
                <thead><tr style={{background:"var(--bg-soft)"}}>
                  <th style={th}>Name</th><th style={th}>Email</th><th style={th}>Phone</th>
                  <th style={th}>Role</th><th style={th}>Change Role</th><th style={{padding:12}}></th>
                </tr></thead>
                <tbody>{users.map(u => (
                  <tr key={u.id} style={{borderBottom:"1px solid var(--border)"}}>
                    <td style={{padding:12,fontWeight:600,color:"var(--navy)"}}>{u.name}</td>
                    <td style={td}>{u.email}</td>
                    <td style={td}>{u.phone}</td>
                    <td style={{padding:12}}>{roleBadge(u.role)}</td>
                    <td style={{padding:12}}>
                      <select value={u.role} onChange={e => changeRole(u.id, e.target.value)}
                        style={{padding:"6px 10px",borderRadius:8,border:"1px solid var(--border)"}}>
                        {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
                      </select>
                    </td>
                    <td style={{padding:12}}>
                      <button className="btn btn-sm" style={{background:"#fdecec",color:"#dc2626"}} onClick={() => delUser(u.id, u.name)}>
                        <i className="fa-solid fa-trash"></i>
                      </button>
                    </td>
                  </tr>))}
                </tbody>
              </table>
            </div>
          </div>)}

        {tab === "jobs" && (
          <div className="dash-panel">
            <h4>All Jobs ({jobs.length})</h4>
            <div style={{overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}>
                <thead><tr style={{background:"var(--bg-soft)"}}>
                  <th style={th}>Title</th><th style={th}>Category</th><th style={th}>Location</th>
                  <th style={th}>Pay</th><th style={th}>Employer</th><th style={th}>Apps</th>
                  <th style={th}>Status</th><th style={{padding:12}}></th>
                </tr></thead>
                <tbody>{jobs.map(j => (
                  <tr key={j.id} style={{borderBottom:"1px solid var(--border)"}}>
                    <td style={{padding:12,fontWeight:600,color:"var(--navy)"}}>{j.title}</td>
                    <td style={td}>{j.category}</td>
                    <td style={td}>{j.location}</td>
                    <td style={{padding:12,color:"var(--green)",fontWeight:600}}>Rs. {Number(j.pay).toLocaleString()}</td>
                    <td style={td}>{j.employerName}</td>
                    <td style={{padding:12}}>{j.applications}</td>
                    <td style={{padding:12}}><span className="jc-badge verified">{j.status}</span></td>
                    <td style={{padding:12}}>
                      <button className="btn btn-sm" style={{background:"#fdecec",color:"#dc2626"}} onClick={() => delJob(j.id, j.title)}>
                        <i className="fa-solid fa-trash"></i>
                      </button>
                    </td>
                  </tr>))}
                </tbody>
              </table>
            </div>
          </div>)}
      </main>
    </div>
  );
}

/* ============ APP ROOT ============ */
function App() {
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState(() => store.get("dw_user", null));
  const route = useRoute();

  useEffect(() => { const t = setTimeout(() => setLoading(false), 900); return () => clearTimeout(t); }, []);

  const onLogin = (data) => {
    const u = { id:data.id, name:data.name, email:data.email, role:data.role };
    store.set("dw_user", u); localStorage.setItem("dw_token", data.token); setUser(u);
  };
  const onLogout = () => { localStorage.removeItem("dw_user"); localStorage.removeItem("dw_token"); setUser(null); go("/"); };

  // split "/jobs?category=Cleaning" into path + query object
  const [path, qs] = route.split("?");
  const query = {};
  if (qs) qs.split("&").forEach(pair => { const [k,v] = pair.split("="); if (k) query[k] = decodeURIComponent(v || ""); });

  let page;
  switch (path) {
    case "/jobs":      page = <Jobs user={user} query={query} />; break;
    case "/job":       page = <JobDetails user={user} jobId={Number(query.id || 0)} />; break;
    case "/about":     page = <About />; break;
    case "/features":  page = <Features />; break;
    case "/pricing":   page = <Pricing />; break;
    case "/login":     page = <Login onLogin={onLogin} />; break;
    case "/register":  page = <Register onLogin={onLogin} query={query} />; break;
    case "/dashboard": page = <Dashboard user={user} onLogout={onLogout} />; break;
    case "/admin":     page = <Admin user={user} onLogout={onLogout} />; break;
    case "/contact":   page = <Contact />; break;
    default:           page = <Home />;
  }
  const hideFooter = ["/login","/register","/dashboard","/admin"].includes(path);

  return (
    <React.Fragment>
      {loading && <Preloader />}
      <Navbar user={user} onLogout={onLogout} route={path} />
      {page}
      {!hideFooter && <Footer user={user} />}
    </React.Fragment>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

